
function formatoMoneda(a){if(a=="Carga inicial"){return a}if(a==0){return"0.00"}a=(Math.round((a-0)*100))/100;a=(a==Math.floor(a))?a+".00":((a*10==Math.floor(a*10))?a+"0":a);a=String(a);var e=a.split(".");var d=e[0];var b=e[1]?"."+e[1]:".00";var c=/(\d+)(\d{3})/;while(c.test(d)){d=d.replace(c,"$1,$2")}a=d+b;if(a.charAt(0)=="-"){return"("+a.substr(1)+")"}return a}function formatoMonedaPeso(a){if(a==0){return"$0.00"}a=(Math.round((a-0)*100))/100;a=(a==Math.floor(a))?a+".00":((a*10==Math.floor(a*10))?a+"0":a);a=String(a);var e=a.split(".");var d=e[0];var b=e[1]?"."+e[1]:".00";var c=/(\d+)(\d{3})/;while(c.test(d)){d=d.replace(c,"$1,$2")}a=d+b;if(a.charAt(0)=="-"){return"($"+a.substr(1)+")"}return"$"+a}function formatoMonedaABS(a){if(a=="Carga inicial"){return a}if(a==0){return"0.00"}a=(Math.round((a-0)*100))/100;a=(a==Math.floor(a))?a+".00":((a*10==Math.floor(a*10))?a+"0":a);a=String(a);var e=a.split(".");var d=e[0];var b=e[1]?"."+e[1]:".00";var c=/(\d+)(\d{3})/;while(c.test(d)){d=d.replace(c,"$1,$2")}a=d+b;if(a.charAt(0)=="-"){return a.substr(1)}return a}function cleanComa(a){a=a.replace(/\,/g,"");return a}function cleanFormatoMoneda(a){a=a.replace(/\.00/g,"");return a};